(()=>{const o=document.querySelector("#tutor-form");if(!o)return;const t=document.querySelector("#tutor-status"),r=document.querySelector("#tutor-answer"),a=o.querySelector('button[type="submit"]');o.addEventListener("submit",async u=>{u.preventDefault(),t.textContent="Preparing an answer\u2026",r.textContent="",a.disabled=!0;try{const e=await fetch("/api/lesson-questions",{method:"POST",headers:{"Content-Type":"application/json",Accept:"application/json"},credentials:"same-origin",body:JSON.stringify({slug:document.body.dataset.lessonSlug,question:document.querySelector("#tutor-question").value})}),n=await e.json();if(e.status===401){t.textContent="Sign in with Google to ask the lesson tutor.";const s=document.createElement("a");s.href="/account",s.textContent=" Sign in",t.append(s);return}if(!e.ok)throw new Error(n.error||"The lesson tutor could not answer just now.");r.textContent=n.answer||"No answer was returned.",t.textContent=`Daily tutor questions used: ${n.usage.used} of ${n.usage.limit}.`}catch(e){t.textContent=e.message}finally{a.disabled=!1}})})();
